INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Wispr Flow', 'wispr-flow', 'AI voice dictation that turns natural speech into polished text in any app, on desktop and mobile.', 'Wispr Flow is a voice-to-text app that works system-wide on Mac, Windows, iPhone, and Android, converting speech into edited, formatted text inside any application. It removes filler words, adapts formatting to the app in use, supports 100+ languages, and learns a personal dictionary over time. It is used by writers, developers, lawyers, sales teams, and accessibility users who want to replace typing with speaking.', 'https://wisprflow.ai', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'freemium', 'Flow Basic is free with weekly word limits (2,000 words/week on desktop, 1,000 on iPhone). Flow Pro is $15/user/mo or $12/user/mo billed annually with unlimited words; Enterprise is custom-priced with SOC 2 and SSO. New accounts get a 14-day Pro trial.', ARRAY['Dictating emails, documents, and messages instead of typing', 'Voice input for coding tools like Cursor and VS Code', 'Drafting legal notes, case records, and client communications', 'Faster ticket and DM responses for support and sales teams', 'Accessibility-friendly text input for users slowed by keyboards']::text[], ARRAY['Works in any app across Mac, Windows, iOS, and Android', 'AI auto-editing produces clean, formatted text without filler words', 'Personal dictionary, snippets, and 100+ language support', 'Genuine free tier plus a 14-day Pro trial']::text[], ARRAY['Free plan has tight weekly word limits', 'Best results still require reviewing dictated text', 'Full compliance features (SOC 2, enforced HIPAA) gated to Enterprise']::text[], ARRAY['Writers and knowledge workers with heavy typing loads', 'Developers who want voice input in coding tools', 'Sales, support, and legal professionals', 'Users with accessibility needs']::text[], ARRAY['System-wide dictation in any application', 'AI auto-edits that clean up rambling speech', 'Command mode for voice-driven text editing', 'Personal dictionary and snippet shortcuts', '100+ languages with automatic detection', 'Privacy mode with zero data retention']::text[], 4.6, true, 'published', 2021, 'Wispr AI', 'Wispr Flow Review, Pricing, Alternatives | AiCensus', 'Wispr Flow is a voice-to-text app that works system-wide on Mac, Windows, iPhone, and Android, converting speech into edited, formatted text inside any app', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Superwhisper', 'superwhisper', 'Voice-to-text app with on-device AI models for private dictation on macOS, Windows, and iOS.', 'Superwhisper is an AI dictation app that runs Whisper models locally on the device, so audio never has to leave the user''s machine, with optional cloud models for higher accuracy. Beyond dictation in any app, it offers file and meeting transcription, custom modes, and integrations aimed at driving agentic coding tools like Cursor and Claude Code by voice. It is built by an independent developer and popular with privacy-conscious professionals and developers.', 'https://superwhisper.com', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'freemium', 'Free tier includes unlimited use of small local models and voice-to-text in any app. Pro is listed by third-party sources at $8.49/mo, $84.99/yr, or a $249.99 lifetime license; the official pricing page was not directly fetchable at review time.', ARRAY['Private, offline dictation for sensitive professional work', 'Voice prompting of AI coding agents like Cursor and Claude Code', 'Transcribing meetings and audio or video files', 'Writing long-form text faster than typing', 'Multilingual dictation and translation']::text[], ARRAY['On-device processing keeps audio private by default', 'Choice of local and cloud AI models with custom modes', 'Usable free tier rather than a time-limited trial', 'Lifetime license option avoids a recurring subscription']::text[], ARRAY['Local models are less accurate than the largest cloud models', 'Model downloads and settings can feel technical for casual users', 'Cloud model usage can add per-provider API costs']::text[], ARRAY['Privacy-conscious professionals such as lawyers and clinicians', 'Developers driving agentic coding tools by voice', 'Mac and iOS users who want offline dictation', 'Writers who prefer a one-time purchase option']::text[], ARRAY['System-wide dictation with on-device Whisper models', 'Optional cloud models for higher accuracy', 'Meeting recording and file transcription', 'Custom modes and per-app profiles', '100+ languages with translation', 'Works with agentic coding apps']::text[], 4.3, true, 'published', NULL, 'Superwhisper', 'Superwhisper Review, Pricing, Alternatives | AiCensus', 'Superwhisper is an AI dictation app that runs Whisper models locally on the device, so audio never has to leave the user''s machine, with optional cloud mod', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('VoiceOS', 'voiceos', 'Voice operating system for Mac and Windows that dictates text and executes actions across apps.', 'VoiceOS is a voice assistant for Mac and Windows that combines dictation with an agent layer: users can dictate text in any app, rewrite selected text by voice, and trigger multi-step actions such as sending Slack messages, replying to Gmail, or creating calendar events. Actions run across integrated apps with user confirmation before execution. It is built by WakoAI, a San Francisco startup backed by Y Combinator, and targets founders and professionals who want to replace repetitive keyboard work with voice commands.', 'https://www.voiceos.com', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'paid', '7-day free trial, then Pro at $11.99/month billed annually with unlimited usage. Enterprise is custom-priced with zero data retention, SOC 2 Type II, ISO 27001, and SSO/SAML.', ARRAY['Dictating polished text in any desktop application', 'Sending Slack messages and email replies by voice', 'Creating and moving calendar events hands-free', 'Asking questions about what is on screen', 'Rewriting selected text with voice commands']::text[], ARRAY['Goes beyond dictation to executing real actions across apps', 'Works system-wide on both Mac and Windows', 'Confirmation step before any action is taken', 'Audio not stored on servers unless the user opts in']::text[], ARRAY['No permanent free tier, only a 7-day trial', 'Agent integrations center on Google and Slack ecosystems', 'Young product with a smaller track record than established rivals']::text[], ARRAY['Founders and operators who live in Slack, Gmail, and Calendar', 'Voice-first professionals on Mac or Windows', 'Users who want one tool for dictation plus app actions', 'Teams needing enterprise controls on a voice assistant']::text[], ARRAY['Dictation mode with automatic formatting per app', 'Agent mode for multi-step actions across integrated apps', 'Edit mode for voice-driven rewriting', 'Screen-aware questions and answers', 'Privacy controls with on-device transcript storage option', 'Enterprise tier with SOC 2, ISO 27001, and SSO']::text[], 4.1, true, 'published', 2023, 'WakoAI, Inc.', 'VoiceOS Review, Pricing, Alternatives | AiCensus', 'VoiceOS is a voice assistant for Mac and Windows that combines dictation with an agent layer: users can dictate text in any app, rewrite selected text by v', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Fyxer', 'fyxer', 'AI email assistant that sorts the inbox, drafts replies in your tone, and takes meeting notes.', 'Fyxer connects to Gmail or Outlook and automatically categorizes incoming email, drafts replies matched to the user''s writing tone, and records meetings to produce summaries and follow-ups. It works inside the existing inbox rather than requiring a new email client, and scales from individual professionals to large teams. The company is headquartered in New York and London and was founded by Richard Hollingsworth, Archie Hollingsworth, and Matthew Ffrench.', 'https://fyxer.com', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'paid', 'Starter is $22.50/user/month and Professional is $37.50/user/month, both billed annually ($30 and $50 month-to-month per third-party reviews); Enterprise is custom. A 7-day free trial is offered.', ARRAY['Triaging a high-volume inbox into smart categories', 'Sending tone-matched reply drafts with minimal editing', 'Capturing meeting notes and follow-ups automatically', 'Searching email and meeting history for context', 'Standardizing email workflow across client-facing teams']::text[], ARRAY['Works inside Gmail and Outlook with near-zero setup', 'Drafts learn the user''s tone over time', 'Combines inbox triage, drafting, and meeting notes in one tool', 'SOC 2 Type II, ISO 27001, GDPR, and HIPAA compliance']::text[], ARRAY['No free tier beyond a short trial', 'Does not support Apple Mail', 'Per-seat pricing adds up for larger teams']::text[], ARRAY['Professionals who spend 2+ hours a day on email', 'Sales, consulting, and real estate teams', 'Executives managing heavy meeting schedules', 'Organizations wanting a managed, compliant email assistant']::text[], ARRAY['Automatic inbox categorization and prioritization', 'Reply drafts written in the user''s voice', 'Meeting recording, transcription, and summaries for online and in-person meetings', 'Fyxer Chat for searching email and meeting context', 'Scheduling suggestions and booking links in replies', 'CRM integration on the Professional plan']::text[], 4.2, true, 'published', 2024, 'Fyxer AI Limited', 'Fyxer Review, Pricing, Alternatives | AiCensus', 'Fyxer connects to Gmail or Outlook and automatically categorizes incoming email, drafts replies matched to the user''s writing tone, and records meetings to', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Jace', 'jace', 'AI email agent that organizes the inbox and prepares context-rich reply drafts in your voice.', 'Jace is an AI email assistant that connects to a user''s inbox, labels and prioritizes incoming mail, and prepares reply drafts that pull in context from attachments, calendar, and connected tools like Slack. It also supports custom automation rules and integrations that trigger actions in other business tools when email arrives. Jace is built by Zeta Labs, a London startup founded by former Meta engineers, and is aimed at professionals and teams with heavy email workloads.', 'https://jace.ai', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'paid', '7-day free trial, then credit-based plans: Plus is $25/mo ($20/mo billed annually) for 10,000 monthly credits and 2 inboxes; Pro is $50/mo ($40/mo billed annually) starting at 20,000 credits and up to 8 inboxes. Enterprise is usage-based and custom.', ARRAY['Reviewing pre-written reply drafts instead of composing from scratch', 'Auto-labeling and prioritizing a busy inbox', 'Pulling attachment, calendar, and Slack context into replies', 'Automating follow-up actions via custom rules', 'Triggering tickets and notifications from incoming email']::text[], ARRAY['Drafts include context from attachments and connected tools', 'Self-onboarding with no manual training required', 'Flexible automation rules beyond simple drafting', 'Competitive entry price compared with similar email assistants']::text[], ARRAY['Credit-based metering can be hard to predict', 'Gmail-centric; third-party reviewers note limited provider support', 'Occasionally generates drafts for low-value email']::text[], ARRAY['Founders and operators drowning in inbound email', 'Professionals who want drafts ready on inbox open', 'Teams connecting email to Slack and ticketing tools', 'Power users who want rule-based email automation']::text[], ARRAY['AI reply drafts with attachment and calendar context', 'Automatic labeling by type and priority', 'Custom smart rules for CCs, templates, and actions', 'Business integrations that trigger workflows from email', 'Chat over 1-3 years of email history', 'Support for multiple inboxes and unlimited calendars']::text[], 4.1, true, 'published', 2023, 'Zeta Labs', 'Jace Review, Pricing, Alternatives | AiCensus', 'Jace is an AI email assistant that connects to a user''s inbox, labels and prioritizes incoming mail, and prepares reply drafts that pull in context from at', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Howie', 'howie', 'Email-based AI secretary that schedules and reschedules meetings by handling the back-and-forth.', 'Howie is an AI scheduling secretary that works over email, SMS, and iMessage: users CC Howie on a thread and it negotiates times, sends invites, reschedules, and follows up until the meeting is booked. It learns individual scheduling preferences and manages calendars with a focus on doing one job - calendar management - rather than being a general assistant. The Seattle-based company raised a $6M seed round in 2025 and reports scheduling thousands of meetings per week for over a thousand paying customers.', 'https://howie.ai', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'paid', 'The official site advertises Individual, Team, and custom Enterprise tiers with a free starting option, but does not publish exact prices; third-party comparisons cite Standard around $35/user/month and Pro around $145/user/month.', ARRAY['Booking meetings by CC''ing Howie on an email thread', 'Coordinating group meetings across busy schedules', 'Rescheduling and clearing the calendar on short notice', 'Following up automatically when invitees go quiet', 'Enforcing personal scheduling preferences and focus time']::text[], ARRAY['Handles the entire scheduling conversation end to end', 'Learns flexible, user-defined scheduling preferences', 'Works over email and messaging without a new app to learn', 'Deliberately narrow scope keeps it reliable at its one job']::text[], ARRAY['Scheduling only - no broader email or task assistance', 'Exact pricing is not published on the official site', 'Historically centered on Google Calendar, limiting Outlook shops']::text[], ARRAY['Executives and founders with heavy external meeting loads', 'Sales and recruiting teams scheduling constantly', 'Professionals who want a human-like secretary experience', 'Teams replacing manual EA scheduling work']::text[], ARRAY['CC-based scheduling over email, SMS, and iMessage', 'Automatic follow-ups until meetings are booked', 'Rescheduling and conflict detection', 'Customizable scheduling preferences and rules', 'Calendar audits and focus-time protection', 'Team and Enterprise plans with custom billing and support']::text[], 4.3, true, 'published', NULL, 'Howie', 'Howie Review, Pricing, Alternatives | AiCensus', 'Howie is an AI scheduling secretary that works over email, SMS, and iMessage: users CC Howie on a thread and it negotiates times, sends invites, reschedule', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Littlebird', 'littlebird', 'Ambient AI assistant that reads your screen and meetings so it already knows what you''re working on.', 'Littlebird is a desktop AI assistant for Mac and Windows that builds a private memory of a user''s work by observing the active window, listening to meetings, and connecting to tools like email and calendar. It uses that context to answer questions, take meeting notes, draft emails and documents in the user''s voice, and run scheduled routines such as morning briefings. The San Francisco company launched publicly in late 2025 and raised an $11M seed round led by Lotus Studio.', 'https://littlebird.ai', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'freemium', 'Basic is free with daily usage credits and limited meeting notes. Plus is $17/mo billed annually ($20 monthly), Power is $42/mo billed annually ($50 monthly), and Pro starts at $100/mo; Team starts at $17/seat/mo and Enterprise is custom.', ARRAY['Asking an assistant that already has context on current work', 'Automatic meeting notes and pre-meeting prep', 'Drafting emails and docs informed by real work context', 'Instant cross-app search over things seen on screen', 'Scheduled briefings and recurring routines']::text[], ARRAY['Full work context without manual copy-pasting into a chatbot', 'User controls which apps are visible and can delete data anytime', 'SOC 2 certified with a no-training-on-your-data policy', 'Generous free tier and optional integrations']::text[], ARRAY['Always-on screen observation will not suit every workplace', 'Heavier usage quickly pushes users into higher-priced tiers', 'Cloud storage of captured context requires trusting the vendor']::text[], ARRAY['Knowledge workers juggling many apps, docs, and meetings', 'Founders and managers who want automatic recall', 'Client-facing professionals needing meeting prep and notes', 'Users who want a personal assistant without manual setup']::text[], ARRAY['Screen-aware context across all apps without setup', 'Meeting notes in 10+ languages plus meeting prep', 'Cross-app instant search over observed work', 'Drafting in the user''s voice from real context', 'Scheduled routines like daily briefings', 'Hundreds of optional integrations and MCP access on higher tiers']::text[], 4.2, true, 'published', NULL, 'Littlebird', 'Littlebird Review, Pricing, Alternatives | AiCensus', 'Littlebird is a desktop AI assistant for Mac and Windows that builds a private memory of a user''s work by observing the active window, listening to meeting', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Stilla', 'stilla', 'AI teammate that turns conversations across meetings and tools into completed work.', 'Stilla is a collaborative AI platform that maintains shared memory across an organization''s tools, meetings, and conversations, then acts on it - drafting PRs, posting Slack updates, editing Notion pages, and automating workflows across 3,000+ integrations. It includes AI meeting notes, a coding agent, sandboxed task machines, and an MCP server for extensibility. The Stockholm-based company was founded by Siavash Ghorbani and Kaj Drobin and emerged from stealth in early 2026 with $5M in funding.', 'https://stilla.ai', (SELECT id FROM public.categories WHERE slug = 'agents-automation'), 'freemium', 'Free to start with $100 in usage credits and no card required; ongoing use is credit-based. Detailed paid tier pricing is not published on the public site.', ARRAY['Turning meeting outcomes into tasks and follow-ups automatically', 'Mentioning @Stilla in Slack or Discord to execute work', 'Automating workflows across 3,000+ connected tools', 'Delegating code changes to an agent that opens and reviews PRs', 'Searching shared memory across every connected tool']::text[], ARRAY['Shared memory persists context across tools and conversations', 'Acts directly in tools rather than only suggesting next steps', 'Free starting credits with no card required', 'Open extensibility via MCP server']::text[], ARRAY['Very new product with limited public track record', 'Credit-based pricing is not transparent on the site', 'Capped at 29 members per organization on standard plans']::text[], ARRAY['Product and engineering teams drowning in coordination work', 'Startups that want agentic automation without building it', 'Teams standardizing workflows as reusable skills', 'Organizations wanting one memory layer across their stack']::text[], ARRAY['Shared memory across tools, meetings, and chats', 'Agents that execute work in Slack, Discord, GitHub, and more', 'AI meeting notes with automatic tasks and follow-ups', 'Coding agent that writes, opens, and reviews PRs', '3,000+ integrations plus an MCP server', 'Sandboxed computers for running tasks']::text[], 4.0, true, 'published', 2024, 'Stilla Development AB', 'Stilla Review, Pricing, Alternatives | AiCensus', 'Stilla is a collaborative AI platform that maintains shared memory across an organization''s tools, meetings, and conversations, then acts on it - drafting ', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Demi', 'demi-ai', 'Proactive AI teammate for Mac that drafts replies, books meetings, and clears to-dos before you ask.', 'Demi is a Mac app that works alongside the user, spotting to-dos across connected tools and preparing the actions to clear them - drafting email replies, booking meetings, summarizing threads, and updating CRM records. It shows each planned action for approval before executing, and connects to 100+ tools including Gmail, Google Calendar, Slack, and CRMs. It targets individuals and small teams who want a proactive assistant rather than a chatbot they have to prompt.', 'https://www.demi.ai', (SELECT id FROM public.categories WHERE slug = 'productivity'), 'paid', 'Individual plan is $50/month for the Mac app with upgradeable usage credits; Team pricing is custom with dedicated onboarding and compliance review support.', ARRAY['Approving pre-drafted email replies instead of writing them', 'Booking meetings and managing calendar logistics', 'Summarizing long threads and teeing up follow-ups', 'Keeping the CRM updated from daily work', 'Delegating tasks from any app or screen on Mac']::text[], ARRAY['Proactively surfaces tasks instead of waiting for prompts', 'Approval gate on every action before anything is sent', 'Broad 100+ tool connectivity including CRM and Drive', 'Google-verified app with SOC 2 Type II and CASA Tier II compliance']::text[], ARRAY['Mac-only at present', 'No free tier; $50/month entry is steep for casual users', 'Messaging channels beyond Slack (iMessage, WhatsApp) still upcoming']::text[], ARRAY['Busy executives and founders on Mac', 'Sales and customer-facing professionals', 'Individuals who want delegation rather than a chatbot', 'Small teams standardizing on one assistant']::text[], ARRAY['Proactive task detection across connected tools', 'Drafted replies, meeting booking, and thread summaries', 'Human approval required before any action executes', '100+ integrations including Gmail, Calendar, Slack, and CRMs', 'Callable from any app or screen via the Mac client', 'SOC 2 Type II and CASA Tier II compliance with zero-retention AI vendors']::text[], 3.9, true, 'published', NULL, 'Demi', 'Demi Review, Pricing, Alternatives | AiCensus', 'Demi is a Mac app that works alongside the user, spotting to-dos across connected tools and preparing the actions to clear them - drafting email replies, b', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Anything', 'anything', 'AI agent that turns natural-language descriptions into working apps, sites, and tools.', 'Anything (formerly CreateAnything) is an AI app builder that generates mobile apps, websites, and internal tools from plain-English prompts, with real code, integrations, and custom domains. It targets non-technical founders and small teams who want functional products without hiring developers. Paid tiers add private projects, custom domains, parallel agents, and automated testing.', 'https://www.createanything.com', (SELECT id FROM public.categories WHERE slug = 'coding-development'), 'freemium', 'Free tier available. Pro is $19/mo with 20K monthly credits; Max is $199/mo with 220K credits, parallel agents, and automated testing. Teams pricing is custom.', ARRAY['Building MVP web or mobile apps from prompts', 'Creating internal tools without engineers', 'Prototyping product ideas quickly', 'Launching sites with GPT-powered features and integrations']::text[], ARRAY['Generates functional apps with real code, not just mockups', 'Includes 40+ integrations and AI features out of the box', 'Clear credit-based pricing with a free entry tier']::text[], ARRAY['Credit limits constrain larger or iterative projects', 'Complex apps may still require developer cleanup', 'Branding removal and private projects require a paid plan']::text[], ARRAY['Non-technical founders', 'Indie hackers and solopreneurs', 'Small business owners', 'Product managers prototyping ideas']::text[], ARRAY['Prompt-to-app generation for mobile, web, and tools', 'Built-in GPT-5 and 40+ integrations', 'Custom domains and private projects', 'Max tier with parallel agents and automated testing', 'Credit-based usage system']::text[], 4.2, true, 'published', NULL, 'Anything', 'Anything Review, Pricing, Alternatives | AiCensus', 'Anything (formerly CreateAnything) is an AI app builder that generates mobile apps, websites, and internal tools from plain-English prompts, with real code', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Viktor', 'viktor', 'AI employee inside Slack and Microsoft Teams that completes tasks across 3,200+ tools.', 'Viktor is an AI coworker that operates inside Slack and Microsoft Teams, executing tasks end to end rather than just answering questions. It runs code on its own cloud computer, connects to over 3,200 workplace tools, and can deliver decks, dashboards, reports, and scheduled automations. Built by former Meta engineers and used by thousands of organizations, it is aimed at lean teams offloading repetitive operational work.', 'https://www.viktor.com', (SELECT id FROM public.categories WHERE slug = 'ai-agents'), 'freemium', 'Free to start with up to $100 in credits and all features included, no credit card required. Paid plans start at $50/month.', ARRAY['Automating recurring reports and digests', 'Auditing ad spend and business metrics', 'Building internal dashboards and small apps', 'Running cross-tool workflows from a single chat message']::text[], ARRAY['Delivers finished work products, not just suggestions', 'Lives natively in Slack and Teams with fast setup', 'Approval controls for irreversible actions', 'Broad integration coverage across 3,200+ tools']::text[], ARRAY['Only useful if your team works in Slack or Teams', 'Per-action credit costs can add up on heavy usage', 'Less customizable than building agents yourself']::text[], ARRAY['Lean startup teams', 'Operations and marketing managers', 'Founders doing too much manual work', 'Teams standardized on Slack or Microsoft Teams']::text[], ARRAY['AI employee with its own cloud computer for running code', '3,200+ tool integrations', 'Scheduled and recurring task automation', 'Approval gates and per-person permissions', 'Company memory that retains decisions and preferences']::text[], 4.3, true, 'published', 2023, 'Viktor', 'Viktor Review, Pricing, Alternatives | AiCensus', 'Viktor is an AI coworker that operates inside Slack and Microsoft Teams, executing tasks end to end rather than just answering questions. It runs code on i', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Marblism', 'marblism', 'A team of six AI employees that runs your inbox, social media, SEO, leads, calls, and contracts.', 'Marblism provides a bundle of six named AI employees — covering inbox management, social media, SEO content, lead generation, phone reception, and contract review — under one subscription. It integrates with Gmail, Outlook, Instagram, LinkedIn, and other common small-business tools and works autonomously in the background. The product targets solopreneurs and small businesses that cannot justify hiring for each role.', 'https://www.marblism.com', (SELECT id FROM public.categories WHERE slug = 'ai-agents'), 'paid', 'Plans start at $24/month on annual billing; every plan includes all 6 AI employees, 50 monthly hours of AI work, unlimited team members, and unlimited businesses. 7-day money-back guarantee.', ARRAY['Triaging and drafting replies to a busy inbox', 'Keeping social media channels posting consistently', 'Publishing SEO blog articles on autopilot', 'Prospecting and outbound lead generation', 'Answering inbound calls and booking appointments']::text[], ARRAY['Six business functions covered in one low-cost subscription', 'No prompting skill required; works autonomously', 'Integrates with common email, social, and calendar tools', '7-day full refund guarantee']::text[], ARRAY['Each AI employee is a generalist, not best-in-class per function', '50-hour monthly work cap with paid top-ups', 'No SOC 2 certification reported, limiting regulated-industry use']::text[], ARRAY['Solopreneurs and one-person businesses', 'Coaches, consultants, and agencies', 'Small e-commerce owners', 'Founders wearing too many hats']::text[], ARRAY['Six role-based AI employees (inbox, social, SEO, leads, calls, legal)', 'Autonomous background operation with approval check-ins', 'Integrations with Gmail, Outlook, Instagram, Facebook, LinkedIn, X', 'AI receptionist with US/CA/UK phone numbers', 'Hours-based usage with monthly resets and top-ups']::text[], 4.0, true, 'published', 2024, 'Marblism', 'Marblism Review, Pricing, Alternatives | AiCensus', 'Marblism provides a bundle of six named AI employees — covering inbox management, social media, SEO content, lead generation, phone reception, and contract', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Appy.AI', 'appy-ai', 'Violet, an AI business partner in Slack and Teams, delegates work to specialist AI agents.', 'Appy.AI lets teams hire AI coworkers that work inside Slack and Microsoft Teams. Users state a goal in plain English and Violet, the coordinator agent, plans the work, delegates to specialist agents, and delivers results with a full audit trail. It connects to 900+ applications and supports recurring, scheduled, and third-party-triggered tasks for lean business teams.', 'https://www.appy.ai', (SELECT id FROM public.categories WHERE slug = 'ai-agents'), 'freemium', 'Free starter with $100 in credits, no card required. Team plans start from $50/month per workspace (not per seat), per the company''s own comparison pages.', ARRAY['Delegating research, writing, and analysis tasks in Slack', 'Running recurring automated business tasks', 'Coordinating multi-step work across connected apps', 'Creating custom AI coworkers for company-specific workflows']::text[], ARRAY['Zero-setup adoption inside existing Slack/Teams channels', 'Coordinator-plus-specialists model produces structured, trackable work', 'Full audit logs and task ownership for accountability', 'Custom AI coworkers can be created by asking']::text[], ARRAY['Pricing beyond the free credits is not published in detail', 'Limited to teams already living in Slack or Teams', 'Newer entrant with a smaller public track record']::text[], ARRAY['Lean teams doing more with less', 'Operations and marketing teams', 'Startups on Slack or Microsoft Teams', 'Managers wanting delegated AI work without new tooling']::text[], ARRAY['Violet coordinator agent that plans and delegates', 'Specialist AI agents for research, writing, analysis, outreach', '900+ app integrations', 'Recurring and third-party-triggered scheduled tasks', 'Activity stream with structured tasks, assets, and audit logs']::text[], 4.1, true, 'published', NULL, 'Appy.AI', 'Appy.AI Review, Pricing, Alternatives | AiCensus', 'Appy.AI lets teams hire AI coworkers that work inside Slack and Microsoft Teams. Users state a goal in plain English and Violet, the coordinator agent, pla', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Chipp', 'chipp', 'No-code platform to build, deploy, and sell branded AI agents without an engineering team.', 'Chipp is a no-code platform for building custom AI agents trained on a business''s own knowledge, deployable to web chat, WhatsApp, Slack, phone, and other channels. It includes built-in payments so builders can sell agents or agent bundles, plus white-label and HIPAA-compliant tiers. Based in Fargo, North Dakota, it reports 125,000+ agents built and 14M+ conversations served.', 'https://www.chipp.ai', (SELECT id FROM public.categories WHERE slug = 'ai-agents'), 'freemium', 'Free to start. Builder $29/mo (+ usage over $10 included), Studio $99/mo (+ usage over $30), Studio Pro $299/mo (+ usage over $100) with zero data retention and HIPAA. Enterprise and add-ons (white-label $999/mo, HIPAA $249/mo) available.', ARRAY['Customer support agents trained on company docs', 'White-label AI chatbots for agency clients', 'Voice agents answering phones and booking appointments', 'Selling branded AI agents as a productized service']::text[], ARRAY['True no-code agent builder with 40+ templates', 'Omnichannel deployment including WhatsApp and phone', 'Built-in monetization and white-label options', 'SOC 2 Type II with HIPAA and zero-data-retention tiers']::text[], ARRAY['Usage-based overages can surprise heavy deployments', 'Advanced privacy features locked to the $299/mo tier', 'Template quality varies; serious agents need tuning']::text[], ARRAY['Small businesses deploying customer-facing AI', 'Agencies reselling branded AI agents', 'Consultants productizing their expertise', 'Nonprofits and community organizations']::text[], ARRAY['Prompt-based agent builder with knowledge uploads', 'Deployment to web, WhatsApp, Slack, Discord, email, voice/phone', 'Built-in Stripe payments for selling agents', 'Voice AI with cloning and call transcripts', 'White-label platform and client management add-ons', 'SOC 2, GDPR, and HIPAA compliance options']::text[], 4.1, true, 'published', 2023, 'Chipp', 'Chipp Review, Pricing, Alternatives | AiCensus', 'Chipp is a no-code platform for building custom AI agents trained on a business''s own knowledge, deployable to web chat, WhatsApp, Slack, phone, and other ', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Durable', 'durable', 'AI website builder that generates a business site in 30 seconds, plus CRM, invoicing, and marketing.', 'Durable is an AI business builder that generates a complete website in about 30 seconds from three questions, then bundles CRM, booking, invoicing, payments, and AI marketing tools in one subscription. It targets solopreneurs and small service businesses that want to replace multiple tools with a single platform. The Vancouver-based company reports millions of websites generated since launch.', 'https://durable.co', (SELECT id FROM public.categories WHERE slug = 'coding-development'), 'freemium', 'Free $0 plan (durable.site subdomain, 5 images/mo, 10 AI chat messages/mo). Launch $25/mo and Grow $49/mo, with discounted annual rates ($22/mo and $41/mo respectively).', ARRAY['Launching a service-business website in minutes', 'Managing leads and customers in a built-in CRM', 'Sending invoices and accepting payments', 'Generating ads, logos, and social content with AI', 'Automating blog posts and review collection']::text[], ARRAY['Fastest path from idea to live site — under a minute', 'Replaces several subscriptions (site, CRM, booking, invoicing)', 'Genuine free tier for testing a business idea', 'Strong user ratings (4.8 on Trustpilot per the site)']::text[], ARRAY['Limited design and code customization versus traditional builders', 'Not designed for full e-commerce', 'Best features (AI agents, SEO/GEO) gated to paid plans']::text[], ARRAY['Solopreneurs and freelancers', 'Local service businesses (trades, coaches, cleaners)', 'First-time business owners', 'Non-technical founders needing an online presence fast']::text[], ARRAY['AI website generation in ~30 seconds', 'Built-in CRM, booking, invoicing, and payments', 'AI agents for blogging, reviews, and lead replies', 'AI image, ad, and logo generation', 'SEO and GEO (AI-search visibility) tools', 'Free custom domain on paid plans']::text[], 4.3, true, 'published', 2021, 'Durable Technologies Inc.', 'Durable Review, Pricing, Alternatives | AiCensus', 'Durable is an AI business builder that generates a complete website in about 30 seconds from three questions, then bundles CRM, booking, invoicing, payment', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Magic Patterns', 'magic-patterns', 'AI design tool that generates UI prototypes matching your existing product and design system.', 'Magic Patterns is an AI design tool for product teams that generates UI from prompts and matches the styling of an existing product or imported design system. It supports rapid prototyping, live team collaboration, GitHub sync, and MCP integration, with export toward production workflows. Developed by North Park Labs, it is used by tens of thousands of product teams for exploring features before engineering commits.', 'https://www.magicpatterns.com', (SELECT id FROM public.categories WHERE slug = 'design-creative'), 'freemium', 'Free tier available. Starter $20/seat/mo (1K credits) and Business $100/seat/mo (5K credits, SSO, usage reporting), billed annually. Enterprise is custom.', ARRAY['Prototyping new features before engineering work', 'Generating UI variations that match an existing design system', 'Testing design concepts directly with customers', 'Collaborating between design and engineering on live prototypes']::text[], ARRAY['Output matches your real product styling, not generic mockups', 'Fast idea-to-prototype loop praised by product teams', 'Design-system import and GitHub/MCP integrations', 'SOC 2 and ISO 27001 certified']::text[], ARRAY['Credit-based pricing makes heavy iteration costly', 'Per-seat pricing scales up quickly for larger teams', 'Generated code typically still needs engineering refinement']::text[], ARRAY['Product designers and product managers', 'Startup founders mocking up features', 'Design engineers and frontend teams', 'Enterprise product teams with design systems']::text[], ARRAY['Prompt-to-UI generation matching existing products', 'Design system import for consistent prototyping', 'Real-time team collaboration and sharing', 'GitHub sync and MCP support', 'Credit-based usage with monthly rollover', 'Enterprise security (SOC 2, ISO 27001, SSO, SCIM)']::text[], 4.4, true, 'published', 2023, 'North Park Labs, Inc.', 'Magic Patterns Review, Pricing, Alternatives | AiCensus', 'Magic Patterns is an AI design tool for product teams that generates UI from prompts and matches the styling of an existing product or imported design syst', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('FLORA', 'flora', 'Infinite canvas that combines 50+ text, image, and video AI models into one creative workflow.', 'FLORA is a node-based infinite canvas for creative professionals that unifies dozens of leading text, image, and video AI models in a single subscription and workflow. Teams use it to ideate, iterate in real time, and scale concepts into production-grade assets, with reusable workflow templates called Techniques. Founded in 2024 by Weber Wong, it counts design firms, film studios, and brand teams among its users.', 'https://www.florafauna.ai', (SELECT id FROM public.categories WHERE slug = 'design-creative'), 'freemium', 'Free plan available. Paid plans are seat-based with a shared workspace usage pool metered at published model rates; third-party listings report Starter around $18/seat/mo, Pro $50, and Max $200.', ARRAY['Creative concepting and mood-board exploration', 'Campaign previz and virtual product shoots', 'Brand identity and asset generation at scale', 'Video pre-production and visual effects experiments', 'Team-based iteration across image and video models']::text[], ARRAY['One subscription covers 50+ models, updated as new ones release', 'Node-based canvas gives real creative control and reproducibility', 'Pooled team usage with per-project cost visibility', 'Strong adoption among professional studios and agencies']::text[], ARRAY['Learning curve for the node-based workflow', 'Usage costs can grow quickly with video models', 'Official per-seat prices are not prominently published on the site']::text[], ARRAY['Creative agencies and design studios', 'Brand and marketing teams', 'Film, fashion, and motion professionals', 'Creative directors exploring AI workflows']::text[], ARRAY['Infinite canvas unifying text, image, and video models', 'FAUNA creative agent for ideation and direction', 'Reusable workflow templates (Techniques)', 'Real-time team collaboration', 'Pooled workspace budget with per-member usage tracking', 'Access to 50+ models including Veo, Kling, FLUX, and Gemini']::text[], 4.3, true, 'published', 2024, 'FLORA', 'FLORA Review, Pricing, Alternatives | AiCensus', 'FLORA is a node-based infinite canvas for creative professionals that unifies dozens of leading text, image, and video AI models in a single subscription a', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Hedra', 'hedra', 'AI creation platform for character-driven video, image, and audio, powered by the Character-3 model.', 'Hedra is a generative media platform best known for turning a single image and audio clip into expressive talking or singing character videos using its proprietary Character-3 model. Hedra Studio combines video, image, and audio generation from its own and partner models on an infinite canvas, with an API for developers. Founded in 2023 in San Francisco and backed by Andreessen Horowitz, it reports over 20 million users.', 'https://www.hedra.com', (SELECT id FROM public.categories WHERE slug = 'video-audio'), 'freemium', 'Free plan with no credit card required. Basic $15/mo (1,500 credits), Creator $30/mo (5,400 credits), Professional and Teams $75/mo (14,400 credits); Enterprise is custom. Monthly credits do not roll over.', ARRAY['Talking-avatar videos from a photo and voice clip', 'Character-driven marketing and social content', 'AI-generated imagery and audio alongside video', 'Developer integrations via the Hedra API']::text[], ARRAY['Character-3 produces notably expressive, lip-synced characters', 'Simple pipeline: one image plus audio yields a finished video', 'Free plan and low entry price for individuals', 'Combines proprietary and partner models in one studio']::text[], ARRAY['Monthly credits expire with no rollover on subscription plans', 'Generation speed gated behind higher tiers', 'Focused on character video rather than general text-to-video']::text[], ARRAY['Content creators and social media teams', 'Marketers producing character-driven video', 'Educators and e-learning producers', 'Developers building on a video-generation API']::text[], ARRAY['Character-3 omnimodal model for talking/singing avatars', 'Hedra Studio infinite canvas for video, image, and audio', 'Hedra Agent for creative planning and execution', 'Credit-based usage across multiple partner models', 'Commercial use rights on all paid plans', 'Enterprise options with private deployments and SSO']::text[], 4.3, true, 'published', 2023, 'Hedra', 'Hedra Review, Pricing, Alternatives | AiCensus', 'Hedra is a generative media platform best known for turning a single image and audio clip into expressive talking or singing character videos using its pro', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Firecrawl', 'firecrawl', 'Web data API that turns websites into clean, LLM-ready markdown, JSON, and search results.', 'Firecrawl is a web crawling, scraping, and search API built for AI applications. It converts URLs to clean markdown, HTML, screenshots, or structured JSON via a single API call, handling JavaScript rendering and proxies automatically. The project is open source with a large community, and the hosted version adds an interact mode for operating pages and an MCP server for agent integrations.', 'https://www.firecrawl.dev/', (SELECT id FROM public.categories WHERE slug = 'ai-agents'), 'freemium', 'Free tier includes 1,000 pages/month. Paid plans: Hobby $16/mo (5,000 pages), Standard $83/mo (100,000 pages), Growth $333/mo (500,000 pages), Scale $599/mo (1M credits), Enterprise custom; prices are annual-billing equivalents.', ARRAY['Feeding web pages into RAG pipelines as clean markdown', 'Powering deep-research agents with search and scrape', 'Crawling entire sites for structured data extraction', 'Lead enrichment and competitive intelligence', 'Giving coding agents web access via MCP']::text[], ARRAY['Open source core with very large community adoption', 'Clean markdown output reduces token usage for LLMs', 'Handles JS-heavy pages without configuration', 'Official MCP server and multi-language SDKs']::text[], ARRAY['Credit system makes costs hard to predict at scale', 'No pay-per-use option; credits mostly do not roll over', 'Advanced features consume extra credits per call']::text[], ARRAY['AI engineers building agents and RAG pipelines', 'Developers needing web data without maintaining scrapers', 'Data teams doing large-scale extraction', 'Startups shipping AI features on live web data']::text[], ARRAY['Scrape, crawl, map, search, and interact endpoints', 'LLM-ready markdown and structured JSON output', 'Automatic JavaScript rendering and smart wait', 'Official MCP server and CLI for agent setup', 'SDKs for Python, Node, Go, Rust, Java, and Elixir', 'Open-source core with hosted enterprise options']::text[], 4.6, true, 'published', 2024, 'SideGuide Technologies (formerly Mendable)', 'Firecrawl Review, Pricing, Alternatives | AiCensus', 'Firecrawl is a web crawling, scraping, and search API built for AI applications. It converts URLs to clean markdown, HTML, screenshots, or structured JSON ', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Context.dev', 'context-dev', 'Web scraping and brand data API for AI agents, turning any URL into markdown or structured data.', 'Context.dev is a developer API that scrapes URLs, crawls sites, and extracts structured data such as markdown, HTML, sitemaps, screenshots, and brand assets (logos, colors, fonts). It targets AI products and agents, offering self-serve API keys, SDKs, and quick integration. Customers include Mintlify, daily.dev, and DocsBot, mainly for onboarding enrichment and agent features.', 'https://www.context.dev/', (SELECT id FROM public.categories WHERE slug = 'ai-agents'), 'freemium', 'Free plan with 500 API credits and no credit card required. Paid plans listed on the pricing page: Developer $25/mo, Pro $149/mo, Scale $499/mo, with a custom Enterprise tier for teams needing more than 2M credits per month.', ARRAY['Enriching SaaS onboarding with brand data from a URL', 'Giving AI agents the ability to read web pages', 'Crawling sites for markdown content at scale', 'Extracting logos, colors, and company info automatically', 'Powering enrichment and automation features in AI products']::text[], ARRAY['Self-serve signup with immediate API key', 'Combines scraping and brand intelligence under one key', 'No credit card needed to test the API', 'Thorough documentation with 10-minute integration reported by users']::text[], ARRAY['Smaller credit allotments than some scraping competitors', 'Brand data focus may be unnecessary for pure scraping needs', 'Relatively young product with a smaller track record']::text[], ARRAY['SaaS founders adding URL-based onboarding enrichment', 'AI product teams building agents that read the web', 'Developers wanting a single API for scrape plus brand data', 'Startups replacing in-house scraping infrastructure']::text[], ARRAY['URL-to-markdown scraping and full-site crawling', 'Brand data API: logos, colors, fonts, company info', 'Structured extraction with AI', 'Self-serve API keys and developer SDKs', 'Screenshots, sitemaps, and HTML output', 'Usage-based credit system across all endpoints']::text[], 4.2, true, 'published', NULL, 'Context.dev', 'Context.dev Review, Pricing, Alternatives | AiCensus', 'Context.dev is a developer API that scrapes URLs, crawls sites, and extracts structured data such as markdown, HTML, sitemaps, screenshots, and brand asset', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Zernio', 'zernio', 'One API to publish, message, advertise, and analyze across 15 social and messaging platforms.', 'Zernio is a unified social media and messaging API for developers and AI agents. It covers publishing, scheduling, analytics, DMs, comments, and ad boosting across 15 channels including Instagram, TikTok, X, LinkedIn, YouTube, WhatsApp, and Bluesky, using official platform APIs. It also provides WhatsApp business numbers with KYC handled, and ships an MCP server so agents can post and manage accounts in natural language.', 'https://www.zernio.com/', (SELECT id FROM public.categories WHERE slug = 'agents-automation'), 'freemium', 'Usage-based per connected account: first 2 accounts free (no card), then $6/account/mo for accounts 3-10, $3/account/mo for 11-100, and $1/account/mo for 101+. X/Twitter API calls, phone numbers, calls, and SMS are billed separately at pass-through rates.', ARRAY['Adding social publishing to a SaaS product without building 15 integrations', 'Letting AI agents post and reply to DMs via MCP', 'Scheduling content across all major platforms from one call', 'Running unified analytics for many client accounts', 'Provisioning WhatsApp business numbers programmatically']::text[], ARRAY['Single OAuth flow and API across 15 channels', 'Uses only official platform APIs, avoiding account bans', 'Transparent graduated per-account pricing with a real free tier', 'MCP server with 280+ tools for agent workflows']::text[], ARRAY['Developer-oriented; requires API skills or no-code connectors', 'X/Twitter usage costs extra at pass-through rates', 'Per-account billing can add up for agencies with many clients']::text[], ARRAY['Developers building social features into products', 'Agencies managing many client social accounts', 'Teams adding WhatsApp messaging without regulatory paperwork', 'Builders wiring AI agents to social channels']::text[], ARRAY['Unified posting, scheduling, and analytics across 15 platforms', 'Single OAuth connection flow, no per-platform dev apps', 'Unified inbox for DMs, comments, and reviews', 'Ad boosting across multiple ad networks', 'WhatsApp number provisioning with KYC handled', 'MCP server for natural-language agent control']::text[], 4.3, true, 'published', NULL, NULL, 'Zernio Review, Pricing, Alternatives | AiCensus', 'Zernio is a unified social media and messaging API for developers and AI agents. It covers publishing, scheduling, analytics, DMs, comments, and ad boostin', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Peec AI', 'peec-ai', 'AI search analytics tracking how brands appear in ChatGPT, Perplexity, Gemini, and other AI answers.', 'Peec AI is a Berlin-based platform that measures brand visibility, position, and sentiment in AI-generated search answers across models like ChatGPT, Perplexity, and Google AI Overviews. Marketing teams track prompts, citations, and competitors with daily refresh, and export reporting via Looker Studio or API. It is used by over a thousand brands and agencies and has raised about $29M in venture funding.', 'https://peec.ai/', (SELECT id FROM public.categories WHERE slug = 'data-analytics'), 'paid', 'Brand plans: Starter $95/mo (50 prompts, 1 project), Pro $245/mo (150 prompts, 2 projects), Advanced $495/mo (350 prompts, 5 projects), Enterprise custom; agency plans from $245/mo. Annual billing saves about 15%, and a 7-day free trial is offered.', ARRAY['Monitoring brand mentions in AI search answers', 'Tracking prompt-level visibility versus competitors', 'Measuring sentiment and position in LLM responses', 'Reporting AI visibility to clients via Looker Studio', 'Informing GEO (generative engine optimization) strategy']::text[], ARRAY['Purpose-built for AI search visibility rather than retrofitted SEO metrics', 'Unlimited users on every plan', 'Daily tracking cadence on all self-serve tiers', 'Strong multi-country and multilingual coverage']::text[], ARRAY['Only 3 AI models included per plan; extra models cost more', 'Monitoring-focused, with limited built-in optimization guidance', 'Higher entry price than some newer competitors']::text[], ARRAY['Marketing and SEO teams at mid-size to enterprise brands', 'Agencies reporting AI visibility to multiple clients', 'Growth teams building a GEO practice', 'Global brands needing multi-market tracking']::text[], ARRAY['Prompt tracking across major AI search models', 'Visibility, position, and sentiment metrics', 'Competitor share-of-voice comparisons', 'Daily data refresh on all plans', 'Looker Studio integration and CSV exports', 'Multi-country and multi-language tracking']::text[], 4.4, true, 'published', 2025, 'Peec AI', 'Peec AI Review, Pricing, Alternatives | AiCensus', 'Peec AI is a Berlin-based platform that measures brand visibility, position, and sentiment in AI-generated search answers across models like ChatGPT, Perpl', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Ranked AI', 'ranked-ai', 'Fully managed AI SEO and PPC combining tracking software with a team that implements the work.', 'Ranked AI is a hybrid software-plus-service offering for search marketing. Its platform includes keyword and AI-prompt tracking, audits, backlink monitoring, and local heatmaps, while its team writes content, builds links, and implements on-page fixes. Plans are month-to-month starting at $99 per website, with white-label options for agencies.', 'https://ranked.ai/', (SELECT id FROM public.categories WHERE slug = 'research-search'), 'paid', 'Standard $99/mo per website (25 target keywords, 1 article/week), Plus $198/mo (50 keywords, 2 articles/week), Enterprise $349/mo (100 keywords, 4 articles/week, dedicated account executive). Month-to-month with a free trial and no contracts.', ARRAY['Outsourcing SEO execution for local and niche businesses', 'Tracking both traditional rankings and AI search visibility', 'Getting weekly blog content produced and published', 'Reselling SEO under an agency''s own brand', 'Managing PPC campaigns with specialist oversight']::text[], ARRAY['Service included, not just software dashboards', 'Low entry price at $99/mo with no contracts', 'No-limits keyword and prompt tracking on all plans', 'White-label option for agencies']::text[], ARRAY['Priced per website, so multi-site costs scale linearly', 'Content output volume is capped per plan tier', 'Hybrid model means results depend on the assigned team']::text[], ARRAY['Small and local businesses without in-house SEO staff', 'Multi-location businesses needing managed search', 'Agencies wanting a white-label SEO stack', 'Teams wanting both AI visibility tracking and execution']::text[], ARRAY['Unlimited keyword and AI prompt tracking', 'Weekly managed blog content and web copy', 'On-page optimization and backlink acquisition', 'Local heatmaps and GBP management', 'GA, GSC, and GBP integrations', 'White-label dashboard, reports, and client portal']::text[], 4.1, true, 'published', NULL, 'Ranked AI', 'Ranked AI Review, Pricing, Alternatives | AiCensus', 'Ranked AI is a hybrid software-plus-service offering for search marketing. Its platform includes keyword and AI-prompt tracking, audits, backlink monitorin', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Subscribr', 'subscribr', 'AI assistant for YouTube that finds outlier video ideas and writes scripts in your channel''s voice.', 'Subscribr is a YouTube-focused AI tool that analyzes a creator''s channel and niche to surface data-backed video ideas ranked by outlier performance, then generates ready-to-film scripts with hooks, structure, and retention-focused pacing. It also offers competitor channel tracking, an AI thumbnail generator, and voice matching trained on the creator''s existing content. Billing is annual only, with a low-cost 7-day trial.', 'https://subscribr.ai/', (SELECT id FROM public.categories WHERE slug = 'video-audio'), 'paid', 'Annual billing only; the Creator plan is listed at $299/year on the site''s checkout. New users can start with a $7 trial for the first 7 days, and a 30-day money-back guarantee is offered.', ARRAY['Generating YouTube video ideas based on outlier data', 'Writing long-form scripts that match a creator''s voice', 'Tracking competitor channels for topic opportunities', 'Producing thumbnails from script concepts', 'Speeding up pre-production for faceless channels']::text[], ARRAY['Purpose-built for YouTube rather than generic AI writing', 'Idea generation grounded in live outlier video data', 'Voice matching keeps scripts on-brand', 'Low-risk $7 trial and 30-day refund policy']::text[], ARRAY['Annual billing only; no monthly subscription option', 'Optimized for English; other languages need manual polish', 'Focused on pre-production, no editing or publishing tools']::text[], ARRAY['YouTube creators publishing long-form content', 'Faceless channel operators producing at volume', 'Video marketers scripting educational or story content', 'Creators who struggle with topic research and hooks']::text[], ARRAY['Outlier video idea generator using live YouTube data', 'Script writing with hooks, structure, and outros', 'Voice matching trained on the user''s channel', 'Competitor channel tracking', 'AI thumbnail generation from script ideas', 'Built-in research agents with web search']::text[], 4.2, true, 'published', NULL, NULL, 'Subscribr Review, Pricing, Alternatives | AiCensus', 'Subscribr is a YouTube-focused AI tool that analyzes a creator''s channel and niche to surface data-backed video ideas ranked by outlier performance, then g', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Typa', 'typa', 'AI content engine that drafts on-brand social posts from voice notes, links, and your knowledge base.', 'Typa is an AI content platform that learns a brand''s voice and opinions, then drafts and schedules posts for X, LinkedIn, Bluesky, and Medium. Users can reach it through iMessage, Slack, voice calls, or the web app, and every draft waits for human approval before publishing. A self-updating knowledge base keeps research and drafts grounded in the company''s actual material.', 'https://www.typa.ai/', (SELECT id FROM public.categories WHERE slug = 'writing-content'), 'freemium', 'Free plan at $0/mo with $3 of usage credits. Pro is $17/mo plus $10 per connected social account (one connection included). A managed ''Founder Mode'' ghostwriting service is available at custom pricing.', ARRAY['Drafting social posts that match a founder''s voice', 'Turning voice notes and links into publishable threads', 'Scheduling content across X, LinkedIn, Bluesky, and Medium', 'Maintaining a knowledge base that informs drafts', 'Delegating content review workflows to a team channel']::text[], ARRAY['Voice cloning produces drafts that read authentically', 'Works inside iMessage, Slack, and voice calls', 'Human approval required before anything posts', 'Generous free entry point for testing']::text[], ARRAY['Per-account connection fees add to the base subscription', 'Publishing coverage limited to a few text-first platforms', 'Young product with a small public track record']::text[], ARRAY['Founders and executives building a personal brand', 'Small marketing teams running social content', 'Creators who think out loud and want drafts from voice notes', 'Brands wanting ghostwriting with approval control']::text[], ARRAY['Brand voice matching across all drafts', 'Drafting from voice notes, links, and research', 'Multi-surface access: iMessage, Slack, voice, web', 'Approval workflow; nothing auto-publishes', 'Self-updating knowledge base', 'Scheduling to X, LinkedIn, Bluesky, and Medium']::text[], 4.0, true, 'published', NULL, NULL, 'Typa Review, Pricing, Alternatives | AiCensus', 'Typa is an AI content platform that learns a brand''s voice and opinions, then drafts and schedules posts for X, LinkedIn, Bluesky, and Medium. Users can re', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Riverflow', 'riverflow', 'AI creative platform that generates on-brand images, videos, and ads trained on your visual identity.', 'Riverflow is an AI creative tool for marketing teams that trains on a brand''s visual identity, values, and products to generate consistent campaign assets. It produces product photography-style images, static ads, and videos for channels like Meta, TikTok, email, and print, with a credit-based pricing model and commercial usage rights. An MCP integration lets teams generate assets from Claude, ChatGPT, or Codex.', 'https://www.riverflow.ai/', (SELECT id FROM public.categories WHERE slug = 'image-generation'), 'freemium', 'Free plan with 50 credits/day for one brand. Paid plans per the official help center: Starter $39/mo ($29/mo annual, 2,250 credits), Growth $99/mo ($74/mo annual, 6,000 credits), Scale $249/mo ($187/mo annual, 16,000 credits), Enterprise custom.', ARRAY['Generating on-brand product photography without shoots', 'Producing static ads and videos for paid social campaigns', 'Scaling creative output across multiple brands', 'Creating campaign assets in hours instead of weeks', 'Generating visuals directly from AI chat tools via MCP']::text[], ARRAY['Brand training keeps outputs visually consistent', 'Covers images, static ads, and video in one credit system', 'Commercial usage rights included on all plans', 'Free daily-credit plan for evaluation']::text[], ARRAY['Credit math differs per asset type, complicating budgeting', 'Lower tiers cap brand profiles and custom styles', 'Best results require upfront brand training effort']::text[], ARRAY['E-commerce and consumer brand marketing teams', 'Agencies producing ad creative for multiple brands', 'Growth teams iterating on paid social creative', 'Creative teams replacing routine photoshoots']::text[], ARRAY['Custom brand training on visual identity and products', 'Image, static ad, and video generation', 'Campaign-ready output for Meta, TikTok, email, and print', 'MCP connection to Claude, ChatGPT, and Codex', 'Custom scene and style training', 'Expert artworking support on higher tiers']::text[], 4.2, true, 'published', NULL, NULL, 'Riverflow Review, Pricing, Alternatives | AiCensus', 'Riverflow is an AI creative tool for marketing teams that trains on a brand''s visual identity, values, and products to generate consistent campaign assets.', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('intellijend', 'intellijend', 'Music marketing platform that runs optimized Meta ads and tracks Spotify popularity scores for artists.', 'intellijend is a marketing automation platform for independent musicians that builds and optimizes Meta (Facebook/Instagram) ad campaigns aimed at streaming growth. It front-loads ad spend around releases, tests multiple creatives with automatic pausing of underperformers, and tracks Spotify''s internal popularity scores to time algorithmic playlist pushes. The company reports usage by over 10,000 artists.', 'https://www.intellijend.com/', (SELECT id FROM public.categories WHERE slug = 'music-audio'), 'paid', 'Subscription from $24.99/month, with Meta ad spend billed separately (the platform''s guidance centers on roughly $10/day campaign budgets). Annual subscribers receive monthly ad creative packs.', ARRAY['Launching Meta ad campaigns for new music releases', 'Triggering Spotify algorithmic playlists with timed ad spend', 'Tracking Spotify popularity scores release-over-release', 'Testing ad creatives systematically without Meta Ads Manager expertise', 'Growing monthly listeners as an independent artist']::text[], ARRAY['Purpose-built for music promotion, not generic ad tooling', 'Automates Meta campaign structure and creative testing', 'Surfaces Spotify popularity data that is otherwise hidden', 'Strong user reviews for support and results']::text[], ARRAY['Total cost requires meaningful ad spend on top of the subscription', 'Results depend heavily on music quality and creative', 'Narrow focus; only useful for streaming-focused music marketing']::text[], ARRAY['Independent artists releasing music regularly', 'Artist managers running release campaigns', 'Small labels promoting streaming growth', 'Musicians without Meta Ads Manager experience']::text[], ARRAY['Automated Meta ads campaign creation for music', 'Front-loaded release-day budget strategy', 'Spotify popularity score tracking', 'Multi-creative ad testing with auto-optimization', 'Ad spend overlayed on streaming metrics', 'Educational guides on Spotify algorithm mechanics']::text[], 4.1, true, 'published', NULL, 'intellijend', 'intellijend Review, Pricing, Alternatives | AiCensus', 'intellijend is a marketing automation platform for independent musicians that builds and optimizes Meta (Facebook/Instagram) ad campaigns aimed at streamin', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Chatbase', 'chatbase', 'Platform for building and deploying AI agents for customer support, sales, and product guidance.', 'Chatbase lets teams train AI agents on their own content (websites, docs, files) and deploy them across live chat, email, phone, Slack, WhatsApp, and other channels. It includes analytics, testing, integrations with helpdesks and CRMs, and AI Actions that let agents take steps in connected systems. The company reports over 10,000 business customers and holds SOC 2 Type II, GDPR, and HIPAA-eligible compliance posture.', 'https://www.chatbase.co', (SELECT id FROM public.categories WHERE slug = 'chatbots-assistants'), 'freemium', 'Free plan at $0 with 50 message credits/month. Paid plans billed annually: Hobby $32/mo, Standard $120/mo, Pro $400/mo; Enterprise custom. Add-ons include extra agents and branding removal.', ARRAY['Automating customer support across chat, email, and voice', 'Building a sales agent that qualifies and guides prospects', 'Embedding a docs-trained chatbot on a website', 'Deflecting repetitive tickets from human support teams', 'Running product guidance and onboarding conversations']::text[], ARRAY['Fast no-code setup and training on own data', 'Broad channel and helpdesk/CRM integration coverage', 'Free tier and transparent tiered pricing', 'Compliance posture (SOC 2 Type II, GDPR, HIPAA-eligible)']::text[], ARRAY['Message-credit model can get expensive at higher volumes', 'Key capabilities (more models, actions, seats) locked to upper tiers', 'Branding removal costs extra on lower plans']::text[], ARRAY['Support teams automating repetitive inquiries', 'SaaS and e-commerce businesses', 'Agencies building chatbots for clients', 'Product teams adding in-app guidance']::text[], ARRAY['AI agents trained on websites, docs, and files', 'Deployment across chat, email, phone, Slack, WhatsApp, Messenger, Instagram', 'AI Actions for tasks in Stripe, Shopify, Calendly, and custom APIs', 'Analytics on topics, sentiment, and resolution rates', 'Playground testing and agent debugging tools', 'Helpdesk integrations (Zendesk, Intercom, Salesforce, HubSpot)']::text[], 4.5, true, 'published', 2023, 'Chatbase, Inc.', 'Chatbase Review, Pricing, Alternatives | AiCensus', 'Chatbase lets teams train AI agents on their own content (websites, docs, files) and deploy them across live chat, email, phone, Slack, WhatsApp, and other', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Watermelon', 'watermelon', 'AI agent for customer service that resolves conversations across chat, email, and social channels.', 'Watermelon provides an AI agent that answers customer questions, executes actions in connected systems, and hands off to humans through a shared inbox when needed. It supports website chat, email, WhatsApp, Facebook Messenger, and Instagram, and integrates with e-commerce platforms such as Shopify and WooCommerce. The company is ISO 27001 certified and hosts data in the EU.', 'https://watermelon.ai', (SELECT id FROM public.categories WHERE slug = 'chatbots-assistants'), 'freemium', 'Free plan includes 50 conversations/month. Paid tiers (Starter, Advanced, Business) raise limits to 250, 500, and 1,000 conversations/month with add-ons at EUR 25/month each; exact euro prices were not shown in the fetched page text. Yearly billing saves 15%.', ARRAY['Automating order status and returns questions for e-commerce', 'Providing 24/7 support outside office hours', 'Centralizing chat, email, WhatsApp, and social DMs in one inbox', 'Reducing phone support volume with self-service AI answers']::text[], ARRAY['Genuine free plan for testing and small volumes', 'Strong e-commerce integrations (Shopify, WooCommerce, Returnless)', 'EU data hosting and ISO 27001 certification', 'Clear conversation-based pricing model']::text[], ARRAY['Conversation limits are low on entry plans', 'Actual plan prices not clearly published on the pricing page', 'Extra agents, users, and conversations all cost add-on fees']::text[], ARRAY['E-commerce and retail support teams', 'European SMBs needing GDPR-compliant automation', 'Leisure and education organizations with high inquiry volume']::text[], ARRAY['AI agent trained via website scraping and file upload', 'Unified inbox with seamless human handoff', 'AI Actions (handoff, search, apps, API calls)', 'Channels: website chat, email, WhatsApp, Messenger, Instagram DM', 'Shopify, WooCommerce, Lightspeed, Magento, BigCommerce integrations', 'Analytics on automation rate and team performance']::text[], 4.2, true, 'published', NULL, 'Watermelon', 'Watermelon Review, Pricing, Alternatives | AiCensus', 'Watermelon provides an AI agent that answers customer questions, executes actions in connected systems, and hands off to humans through a shared inbox when', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Weav', 'weav', 'AI customer support agent trained on your website, docs, and resolved tickets.', 'Weav builds a support agent by connecting to a company''s website, documentation, and files, and claims to resolve over 70% of customer questions autonomously. It also learns from a team''s resolved tickets to match brand voice and improve over time. Setup is no-code and a free tier is offered to get started.', 'https://weav.com', (SELECT id FROM public.categories WHERE slug = 'chatbots-assistants'), 'freemium', 'The site advertises free setup and ''pricing that scales with your business,'' but no published plan prices were visible on the fetched pages; details require signing up or contacting the team.', ARRAY['Deflecting repetitive support emails and tickets', 'Founders and small teams handling support without hiring', 'Keeping an AI agent current as documentation changes', 'Answering customers 24/7 in the company''s tone of voice']::text[], ARRAY['Very fast no-code setup from existing docs and site content', 'Learns continuously from resolved tickets', 'Free entry point for small teams']::text[], ARRAY['No public price list to evaluate cost upfront', 'Young product with limited public track record', 'Fewer published integrations than established competitors']::text[], ARRAY['Startup founders handling support themselves', 'Small support teams', 'SaaS companies with documentation-heavy products']::text[], ARRAY['Knowledge engine built from website, docs, and file uploads', 'Learning from real ticket resolutions', 'Brand voice matching', 'Unified workspace for AI and human support', 'No-code launch in minutes']::text[], 4.0, true, 'published', NULL, NULL, 'Weav Review, Pricing, Alternatives | AiCensus', 'Weav builds a support agent by connecting to a company''s website, documentation, and files, and claims to resolve over 70% of customer questions autonomous', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Heyy', 'heyy', 'AI employees that automate sales, marketing, and support on WhatsApp, Instagram, and Messenger.', 'Heyy lets businesses create configurable ''AI Employees'' that handle customer conversations across WhatsApp, Instagram, Messenger, and a website chat widget. It includes campaigns, a mini-CRM, a shared inbox, automations, and API access, with credit-based usage for AI interactions. Setup is no-code, and integrations connect CRMs, e-commerce, and ticketing tools.', 'https://heyy.ai', (SELECT id FROM public.categories WHERE slug = 'chatbots-assistants'), 'paid', 'Hobby $49/mo (1 user, 1,000 credits, 1 AI employee), Pro $149/mo (5 users, 6,000 credits), Ultra $499/mo (10 users, 20,000 credits); Enterprise custom. Annual billing gives two months free; credits and WhatsApp messages cost extra.', ARRAY['Automating WhatsApp sales and support conversations', 'Qualifying and capturing leads on Instagram and Messenger', 'Running outbound messaging campaigns', 'Managing all customer chats in one shared inbox']::text[], ARRAY['Strong focus on WhatsApp/Instagram/Messenger commerce', 'No-code AI employee setup with CRM and campaign tools included', 'Published tiered pricing with a free trial']::text[], ARRAY['Credit-based model plus extra WhatsApp message fees complicate cost forecasting', 'Entry plan limited to one user and three channels', 'No permanent free plan']::text[], ARRAY['SMBs selling through WhatsApp and Instagram', 'E-commerce and service businesses', 'Teams wanting a shared inbox with AI automation']::text[], ARRAY['Configurable AI Employees for support, sales, and onboarding', 'WhatsApp, Instagram, Messenger, and website chat channels', 'Campaigns, journeys, and scheduled messaging', 'Mini-CRM and shared inbox', 'Automations and full API access', 'AI Actions connecting to external tools']::text[], 4.1, true, 'published', NULL, NULL, 'Heyy Review, Pricing, Alternatives | AiCensus', 'Heyy lets businesses create configurable ''AI Employees'' that handle customer conversations across WhatsApp, Instagram, Messenger, and a website chat widget', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Comp AI', 'comp-ai', 'AI compliance automation for SOC 2, ISO 27001, HIPAA, GDPR, and more frameworks.', 'Comp AI automates compliance programs by collecting evidence from a company''s stack, mapping it to controls, drafting policies, and answering security questionnaires. Controls map across frameworks, so adding ISO 27001 to an existing SOC 2 program starts largely complete. The platform also bundles expert-run penetration testing and a live Trust Center for sharing compliance status with buyers, and reports 830+ customer companies.', 'https://trycomp.ai', (SELECT id FROM public.categories WHERE slug = 'agents-automation'), 'paid', 'No public rate card; pricing is quoted on a 20-minute scoping call based on frameworks, company size, timeline, and whether audits or penetration testing are included.', ARRAY['Getting SOC 2 audit-ready to close enterprise deals', 'Running multi-framework programs (SOC 2, ISO 27001, HIPAA, GDPR)', 'Automating evidence collection across the tech stack', 'Answering buyer security questionnaires quickly', 'Publishing a live Trust Center for prospects']::text[], ARRAY['Cross-framework control mapping reduces duplicate work', 'Automated evidence collection with 580+ integrations', 'Penetration testing and Trust Center built in', 'Strong customer ratings (4.7/5 on G2 per vendor)']::text[], ARRAY['No transparent public pricing', 'Sales call required before any cost estimate', 'Aimed at B2B SaaS; overkill for very small teams']::text[], ARRAY['B2B SaaS startups pursuing their first SOC 2', 'Scale-ups adding ISO 27001, HIPAA, or GDPR', 'Security and compliance leads at growing companies']::text[], ARRAY['Automated evidence collection mapped to controls', 'Multi-framework support (SOC 2, ISO 27001, HIPAA, GDPR, PCI DSS, NIST, FedRAMP)', 'AI-drafted policies and questionnaire answers', 'Expert-run penetration testing with remediation tracking', 'Live Trust Center for buyers', '580+ stack integrations']::text[], 4.3, true, 'published', NULL, 'Comp AI', 'Comp AI Review, Pricing, Alternatives | AiCensus', 'Comp AI automates compliance programs by collecting evidence from a company''s stack, mapping it to controls, drafting policies, and answering security ques', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('AI Fiesta', 'ai-fiesta', 'One subscription to chat with ChatGPT, Gemini, Claude, Perplexity, Grok, and DeepSeek side by side.', 'AI Fiesta aggregates multiple premium AI models into a single chat interface, letting users compare answers side by side and toggle models mid-conversation. It includes prompt enhancement, image generation, audio transcription, custom projects with system instructions, and a ''Super Fiesta'' mode that auto-selects a model. Launched in August 2025 by YouTuber Dhruv Rathee with TagMango co-founders, it targets price-sensitive users, especially in India with UPI payments.', 'https://aifiesta.ai', (SELECT id FROM public.categories WHERE slug = 'chatbots-assistants'), 'paid', '$12/month or discounted annual billing (India: Rs. 999/month, Rs. 833/month annual) with 3 million tokens/month; premium models consume tokens at 4x. Payments are non-refundable except for billing errors.', ARRAY['Comparing answers from multiple AI models in one window', 'Consolidating several AI subscriptions into one cheaper plan', 'Writing, research, and coding assistance', 'Image generation and audio transcription alongside chat']::text[], ARRAY['Much cheaper than paying for each premium model separately', 'Side-by-side model comparison is genuinely useful', 'India-friendly pricing and UPI payment support', 'Mobile apps and browser access']::text[], ARRAY['Token cap with 4x multiplier on premium models limits heavy use', 'Strict no-refund policy', 'Mixed reception with public criticism of value and marketing claims', 'Aggregated access may lag native apps'' newest features']::text[], ARRAY['Students and professionals on a budget', 'Users in India wanting local payment options', 'People who routinely compare multiple chatbots']::text[], ARRAY['9+ premium models (ChatGPT, Gemini, Claude, Perplexity, Grok, DeepSeek, Kimi, Qwen, Mistral)', 'Side-by-side answer comparison', 'Super Fiesta automatic model selection', 'Prompt enhancer and memory', 'Image generation and audio transcription', 'Custom projects with system instructions']::text[], 3.8, true, 'published', 2025, 'AI Fiesta (co-founded by Dhruv Rathee; payments via TagMango)', 'AI Fiesta Review, Pricing, Alternatives | AiCensus', 'AI Fiesta aggregates multiple premium AI models into a single chat interface, letting users compare answers side by side and toggle models mid-conversation', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Magica', 'magica', 'All-in-one AI platform (formerly Galaxy.ai) bundling thousands of models for text, image, video, and audio.', 'Magica, formerly known as Galaxy.ai, aggregates a large catalog of AI models and tools into a single subscription covering chat, image generation, video, and audio. It provides access to leading models such as GPT, Gemini, Claude, Grok, Perplexity, and Mistral from one interface, plus custom agents and automation features. A free Hobby plan is available alongside paid subscriptions.', 'https://galaxy.ai', (SELECT id FROM public.categories WHERE slug = 'chatbots-assistants'), 'freemium', 'Free Hobby plan with limited AI requests; paid plans reported to start around $15/month. Detailed plan pricing is rendered dynamically on the site and was not captured in the fetched pages.', ARRAY['Replacing multiple AI subscriptions with one account', 'Generating text, images, video, and audio in one place', 'Trying many models without separate signups', 'Building simple custom agents and automations']::text[], ARRAY['Very broad model and tool catalog under one subscription', 'Free tier for evaluation', 'Covers multimodal generation, not just chat']::text[], ARRAY['Rebrand from Galaxy.ai to Magica creates brand confusion', 'Plan pricing not clearly published', 'Depth per tool can lag dedicated single-purpose products']::text[], ARRAY['General users wanting one AI subscription', 'Content creators working across text, image, and video', 'Budget-conscious users consolidating AI tools']::text[], ARRAY['Access to thousands of AI models and tools', 'Chat with GPT, Gemini, Claude, Grok, Perplexity, Mistral', 'Image, video, and audio generation', 'Custom AI agents and automation', 'Single account replacing multiple subscriptions']::text[], 4.0, true, 'published', NULL, 'Galaxy.ai', 'Magica Review, Pricing, Alternatives | AiCensus', 'Magica, formerly known as Galaxy.ai, aggregates a large catalog of AI models and tools into a single subscription covering chat, image generation, video, a', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Supercut', 'supercut', 'AI-powered video messaging: record up to 4K, auto-edit, and share instantly with your team.', 'Supercut is a video messaging and screen recording tool with native macOS and Windows recorders capturing up to 4K. AI features auto-edit recordings (removing silences and filler words), generate chapters, titles, summaries, and multi-language transcripts, and videos are shared instantly via branded links with calls to action, comments, and view analytics. The product holds ISO 27001 and SOC 2 Type II certifications and exposes MCP and API access.', 'https://supercut.ai', (SELECT id FROM public.categories WHERE slug = 'video-audio'), 'paid', 'Pro plan at $15 per seat/month billed yearly, with unlimited viewer seats; no credit card required to start, indicating a free trial or starter access. No other tiers were published on the fetched pricing page.', ARRAY['Async video updates replacing meetings', 'Sales outreach with personalized screen recordings', 'Product demos with auto-chapters and CTAs', 'Team knowledge sharing and walkthroughs']::text[], ARRAY['Polished AI editing (silence/filler removal, auto-chapters)', 'Instant link sharing with branding and analytics', 'Unlimited videos and 4K recording at a modest per-seat price', 'Security certifications (ISO 27001, SOC 2 Type II)']::text[], ARRAY['Single published plan; little pricing flexibility', 'Yearly billing emphasized; monthly terms unclear', 'Crowded category with free or cheaper alternatives (Loom, etc.)']::text[], ARRAY['Sales and customer success teams', 'Remote product and engineering teams', 'Founders and agencies sending video updates']::text[], ARRAY['Native macOS/Windows recorders up to 4K', 'AI auto-edit, auto-chapters, titles, and summaries', 'Transcript and timeline editing with zooms', 'Instant sharing with layouts, branding, and CTAs', 'Comments, reactions, and engagement analytics', 'MCP and API access']::text[], 4.3, true, 'published', NULL, NULL, 'Supercut Review, Pricing, Alternatives | AiCensus', 'Supercut is a video messaging and screen recording tool with native macOS and Windows recorders capturing up to 4K. AI features auto-edit recordings (remov', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Clico', 'clico', 'Browser extension that puts AI writing help inside every text box on the web.', 'Clico is a Chromium browser extension that opens an AI assistant inside any text field via a keyboard shortcut, reading the visible page for context so users can draft, rewrite, summarize, search, or dictate without switching tabs. It works across Gmail, Google Docs, Notion, Slack, LinkedIn, and other sites, requires no API key, and skips password and payment fields for privacy. It launched on Product Hunt in March 2026.', 'https://tryclico.com', (SELECT id FROM public.categories WHERE slug = 'writing-content'), 'freemium', 'Free plan includes 100 AI generations per month with no credit card; a Pro plan adds unlimited generations and premium models, but its price was not published on the fetched site.', ARRAY['Drafting and replying to emails in Gmail without tab switching', 'Rewriting and improving text in Google Docs and Notion', 'Summarizing the current page with a shortcut', 'Dictating messages via voice input', 'Quick contextual research from any webpage']::text[], ARRAY['Works in any text field on any website', 'Reads page context automatically, no copy-pasting', 'Generous free plan and no API key required', 'Privacy-conscious design (skips sensitive fields, no background listening)']::text[], ARRAY['Chromium-only (Chrome, Edge, Brave, Arc)', 'Pro pricing not published', 'Very young product with a small team']::text[], ARRAY['Knowledge workers living in browser-based tools', 'Students writing across web apps', 'Support and sales teams drafting replies all day']::text[], ARRAY['Cmd/Ctrl+O AI dialog inside any text field', 'Page-context awareness for relevant drafts', 'Page summarization via double-tap shortcut', 'Voice input dictation', 'Highlight-to-search', 'Dark mode and Clerk-based authentication']::text[], 4.2, true, 'published', 2026, NULL, 'Clico Review, Pricing, Alternatives | AiCensus', 'Clico is a Chromium browser extension that opens an AI assistant inside any text field via a keyboard shortcut, reading the visible page for context so use', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.tools (name, slug, tagline, description, website_url, category_id, pricing_model, pricing_details, use_cases, pros, cons, who_its_for, key_features, editor_rating, is_verified, status, founded_year, company_name, meta_title, meta_description, pricing_as_of) VALUES ('Maple', 'maple', 'Voice AI for restaurants that answers calls, takes orders, and manages reservations 24/7.', 'Maple is a voice AI platform that answers restaurant phone calls around the clock, taking pickup and delivery orders directly into POS systems (including Toast, SkyTab, and TRAY) and handling reservations through OpenTable and SevenRooms. It also fields catering inquiries, hours, directions, and FAQs, and reports over 1 million calls answered for 1,000+ restaurants with a resolution rate above 90% without human intervention. The New York-based company launched in December 2023 and graduated from the AWS Generative AI Accelerator.', 'https://maple.inc', (SELECT id FROM public.categories WHERE slug = 'ai-agents'), 'paid', 'Pricing is not published on the public site; the company sells through demos and POS-partner channels (TRAY, SkyTab), so plans are quoted per restaurant.', ARRAY['Capturing phone orders missed during peak service', 'Automating reservation bookings over the phone', 'Answering hours, directions, and menu questions 24/7', 'Reducing front-of-house phone interruptions']::text[], ARRAY['Deep POS integrations (Toast, SkyTab, TRAY) send orders straight to the kitchen', 'OpenTable and SevenRooms reservation sync', 'Proven scale: 1M+ calls, 1,000+ restaurants', 'Handles complex modifiers and upsells']::text[], ARRAY['No public pricing; sales process required', 'Restaurants only; not a general-purpose voice agent', 'Order depth trails some competitors on payment capture, per third-party comparisons']::text[], ARRAY['Independent restaurants and multi-location chains', 'High-volume QSR and fast-casual operators', 'Restaurants already on Toast, SkyTab, or TRAY POS']::text[], ARRAY['24/7 AI phone answering for restaurants', 'Phone order capture synced to POS (Toast, SkyTab, TRAY)', 'Reservation management via OpenTable and SevenRooms', 'Catering inquiries, hours, directions, and FAQ handling', 'Upsell suggestions during ordering', 'Call transcripts for staff follow-up']::text[], 4.1, true, 'published', 2023, 'Maple AI Inc.', 'Maple Review, Pricing, Alternatives | AiCensus', 'Maple is a voice AI platform that answers restaurant phone calls around the clock, taking pickup and delivery orders directly into POS systems (including T', '2026-07-20') ON CONFLICT (slug) DO NOTHING;
